<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {localFetch,readJson} from './http'
import Icon from './Icon.vue'
type Settings={etfs:string[];auto_ytd_count:number;auto_ytd_min_rs:number;stock_value:number;cash_value:number;allocation_count:number}
type Etf={symbol:string;name:string;selection?:string;rs_ytd?:number|null;rank_ytd?:number|null;rank_date?:string|null;distribution?:string;error?:string;as_of?:string;start?:string;sample?:number;ytd_total?:number|null;price_return?:number|null;excess_0050?:number|null;drawdown?:number;volatility?:number;position_pct?:number;position_label?:string;market_price?:number;support_1?:number;support_2?:number;resistance_1?:number;resistance_2?:number;distance_support_pct?:number;distance_resistance_pct?:number;swing_action?:string;nav?:number|null;nav_as_of?:string|null;nav_note?:string;premium_pct?:number|null;opportunity_score?:number;recommended?:boolean;allocation_weight?:number;recommended_amount?:number;estimated_price?:number;estimated_units?:number;estimated_lots?:number;estimated_odd_lots?:number;adjustment_action?:string;suggested_trim_amount?:number;estimated_trim_units?:number;rotation_preview_amount?:number;rotation_units?:number;dividends?:{date:string;amount:number}[];curve?:{date:string;value:number}[];source?:string;stale?:boolean;limitations?:string}
type RiskFactor={name:string;weight:number;score:number|null;as_of?:string|null;detail:string;available:boolean}
type Risk={score:number;coverage:number;actionable:boolean;target_equity_pct:number;raw_target_pct:number;previous_target_pct?:number|null;current_equity_pct:number;stock_value:number;cash_value:number;total_assets:number;target_stock_value:number;deployable:number;trim_amount?:number;reserve_cash:number;post_trim_cash?:number;volatility?:number|null;drawdown?:number|null;factors:RiskFactor[];status:string}
type RiskBar={date:string;open:number;high:number;low:number;close:number;ma20:number|null;target_equity_pct:number|null;change_pp:number|null}
type RiskDecision={date:string;created_at:string;target:number;change_pp:number|null;action:string;effective_date:string|null;index_close?:number|null;ma20?:number|null;trend_20_pct?:number|null;above_ma20?:boolean|null}
type RiskHistory={bars:RiskBar[];decisions:RiskDecision[];summary:{start?:string;end?:string;sessions?:number;decision_dates?:number;paired_points?:number;trend_allocation_correlation?:number|null;latest_trend_20_pct?:number|null;rising_market_cuts?:number;message:string;guidance?:string;method?:string}}
type Rotation={from_symbol:string;from_name:string;to_symbol:string;to_name:string;preview_amount:number;from_units:number;to_units:number;trigger:string}
type Plan={count:number;symbols:string[];deployable:number;estimated_used:number;leftover:number;trim_amount?:number;post_trim_cash?:number;adjustments?:string[];rotations?:Rotation[];method:string}
type DailyAnalysis={mode:string;date:string;created_at:string;frozen:boolean;action:'add'|'trim'|'hold';target_equity_pct:number|null;coverage:number|null;summary:string;method:string;selected:{symbol:string;name:string;action:'add'|'trim';amount:number;price?:number|null;estimated_price?:number|null;units?:number|null;position_pct?:number|null;rs_ytd?:number|null;ytd_total?:number|null;reason?:string}[]}
type State={snapshot:null|{id:string;date:string;created_at:string;version?:string;mode?:string;analysis?:DailyAnalysis;settings:Settings;catalog_date?:string|null;plan_symbols?:string[];automatic_symbols?:string[];etfs:Etf[];risk?:Risk;plan?:Plan;warnings:string[]};history:{id:string;date:string;created_at:string}[];risk_history?:RiskHistory;job:{status:string;message:string;errors?:string[]};settings:Settings;etf_method:string}
const state=ref<State|null>(null),error=ref(''),notice=ref(''),busy=ref(false),saving=ref(false),history=ref(''),target=ref(''),search=ref(''),sort=ref('ytd_total'),chartSymbol=ref(''),editing=ref(false),riskHover=ref<number|null>(null)
const form=ref<Settings>({etfs:[],auto_ytd_count:5,auto_ytd_min_rs:90,stock_value:800001,cash_value:1000000,allocation_count:3}),symbols=ref('')
let timer:ReturnType<typeof setTimeout>|undefined,alive=true,epoch=0
const f=(v:number|null|undefined,d=2)=>v==null?'—':v.toLocaleString('zh-TW',{maximumFractionDigits:d})
const pct=(v:number|null|undefined)=>v==null?'—':f(v)+'%'
const units=(v:number|null|undefined)=>{if(v==null)return '—';const n=Math.max(0,Math.floor(v)),lots=Math.floor(n/1000),odd=n%1000;return lots?`${f(lots,0)} 張${odd?' '+f(odd,0)+' 股':''}`:`${f(odd,0)} 股`}
const levelPos=(v:number|undefined,e:Etf)=>{const lo=e.support_2,hi=e.resistance_2;if(v==null||lo==null||hi==null||hi<=lo)return 50;return Math.max(0,Math.min(100,(v-lo)/(hi-lo)*100))}
const tone=(v:number|null|undefined)=>v==null?'':v>0?'positive':v<0?'negative':''
const stamp=(s:string)=>s.replace('T',' ').slice(0,16)
const snap=computed(()=>state.value?.snapshot)
const savedForTarget=computed(()=>target.value?state.value?.history.some(r=>r.date===target.value):!!snap.value)
const etfs=computed(()=>(snap.value?.etfs||[]).filter(e=>!search.value||(e.symbol+e.name).includes(search.value)).sort((a,b)=>{if(sort.value==='recommended')return Number(b.recommended)-Number(a.recommended)||(b.opportunity_score||0)-(a.opportunity_score||0);const key=sort.value as 'ytd_total'|'drawdown'|'volatility'|'position_pct';const av=a[key],bv=b[key];return av==null?1:bv==null?-1:sort.value==='volatility'||sort.value==='position_pct'?av-bv:bv-av}))
const selected=computed(()=>etfs.value.find(e=>e.symbol===chartSymbol.value)||etfs.value.find(e=>!e.error))
const lines=computed(()=>{const rows=selected.value?.curve||[];if(!rows.length)return null;const values=rows.map(r=>r.value),hi=Math.max(...values),lo=Math.min(...values);return {value:rows.map((r,i)=>`${20+i/Math.max(1,rows.length-1)*900},${175-(r.value-lo)/(hi-lo||1)*150}`).join(' '),start:rows[0]!.date,end:rows.at(-1)!.date}})
const riskChart=computed(()=>{const source=state.value?.risk_history?.bars||[];if(!source.length)return null;const values=source.flatMap(r=>[r.low,r.high]),rawLo=Math.min(...values),rawHi=Math.max(...values),pad=Math.max(1,(rawHi-rawLo)*.08),lo=rawLo-pad,hi=rawHi+pad,top=34,bottom=224,left=58,right=918;const priceY=(v:number)=>bottom-(v-lo)/(hi-lo)*(bottom-top),step=(right-left)/Math.max(1,source.length-1),bodyWidth=Math.max(5,Math.min(13,step*.56));const rows=source.map((r,i)=>{const x=left+i*step,openY=priceY(r.open),closeY=priceY(r.close);return {...r,x,openY,closeY,highY:priceY(r.high),lowY:priceY(r.low),bodyY:Math.min(openY,closeY),bodyH:Math.max(2,Math.abs(openY-closeY)),bodyWidth,up:r.close>=r.open,allocationY:r.target_equity_pct==null?null:344-r.target_equity_pct/100*88,allocationH:r.target_equity_pct==null?0:r.target_equity_pct/100*88}});return {rows,ma20:rows.filter(r=>r.ma20!=null).map(r=>`${r.x},${priceY(r.ma20!)}`).join(' '),lo,hi,start:source[0]!.date,end:source.at(-1)!.date,left,right}})
const hoveredRisk=computed(()=>riskChart.value?.rows[riskHover.value??Math.max(0,(riskChart.value?.rows.length||1)-1)])
const hoveredDecision=computed(()=>state.value?.risk_history?.decisions.find(d=>d.date===hoveredRisk.value?.date))
function moveRisk(e:PointerEvent){if(!riskChart.value)return;const rect=(e.currentTarget as SVGElement).getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*970;riskHover.value=Math.max(0,Math.min(riskChart.value.rows.length-1,Math.round((x-riskChart.value.left)/(riskChart.value.right-riskChart.value.left)*Math.max(1,riskChart.value.rows.length-1))))}
async function api(path:string,body?:unknown){const r=await localFetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await readJson(r);if(!r.ok)throw new Error(d.error||'無法讀取策略資料');return d}
async function load(init=false){const token=++epoch;clearTimeout(timer);try{const d:State=await api('/api/strategies'+(history.value?'?id='+encodeURIComponent(history.value):''));if(!alive||token!==epoch)return;state.value=d;if(!d.snapshot?.etfs.some(e=>e.symbol===chartSymbol.value&&!e.error))chartSymbol.value=d.snapshot?.etfs.find(e=>!e.error)?.symbol||'';busy.value=d.job.status==='running';if(init){form.value={etfs:d.settings.etfs,auto_ytd_count:d.settings.auto_ytd_count,auto_ytd_min_rs:d.settings.auto_ytd_min_rs,stock_value:d.settings.stock_value,cash_value:d.settings.cash_value,allocation_count:d.settings.allocation_count};symbols.value=d.settings.etfs.join(', ')}if(busy.value)timer=setTimeout(()=>load(),2000)}catch(e){if(alive){error.value=(e as Error).message;busy.value=false}}}
async function refresh(force=false){error.value='';notice.value='';busy.value=true;history.value='';try{const result=await api('/api/strategies/refresh',{...(target.value?{date:target.value}:{}),force});notice.value=result.cached?'已讀取當日保存規劃，未重新抓取資料。':force?'已開始重新分析；完成後會保存為同日新版本。':'已開始生成每日 ETF 規劃。';await load()}catch(e){error.value=(e as Error).message;busy.value=false}}
async function save(){saving.value=true;error.value='';try{const cfg={...form.value,etfs:symbols.value.split(/[\s,，]+/).filter(Boolean)};await api('/api/strategies/settings',cfg);notice.value='設定已保存；下次 ETF 每日分析採用，既有快照保持原樣。';editing.value=false;await load(true)}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
onMounted(()=>load(true));onUnmounted(()=>{alive=false;epoch++;clearTimeout(timer)})
</script>
<template>
<section class="strategies-page">
 <header class="page-header"><div><div class="eyebrow">RESEARCH · ROLLING ALLOCATION</div><h1>ETF 滾動存股規劃</h1><p>依市場風控與 ETF 位階分批配置，不按固定日期扣款。</p></div><div class="header-actions"><button v-if="savedForTarget" class="secondary" :disabled="busy" @click="refresh(true)">重新分析（建立新版本）</button><button class="primary" :disabled="busy" @click="refresh(false)"><Icon name="refresh" :class="{spinning:busy}"/>{{busy?'ETF 分析中':'生成每日 ETF 規劃'}}</button></div></header>
 <div v-if="error" class="error-banner" role="alert">{{error}}</div><p v-if="notice" role="status">{{notice}}</p>
 <div class="strategy-status"><span>{{state?.job.message||'讀取已保存資料…'}}</span></div>
 <div class="strategy-tools"><label>已保存快照<select v-model="history" @change="load()"><option value="">最新快照</option><option v-for="r in state?.history" :value="r.id" :key="r.id">{{r.date}} · {{stamp(r.created_at)}}</option></select></label><label>更新研究日<input v-model="target" type="date" aria-label="策略更新研究日"></label><span>留空使用最新本機收盤日</span><button @click="editing=!editing">名單與配置設定</button></div>
 <form v-if="editing" class="panel strategy-settings" @submit.prevent="save"><h2>下次 ETF 分析設定</h2><label>自選存股 ETF 代碼（最多12檔）<input v-model="symbols" required placeholder="0050, 006208, 0056"></label><label>自動加入 YTD 強勢（檔）<input v-model.number="form.auto_ytd_count" type="number" min="0" max="7" step="1" required></label><label>最低 YTD RS<input v-model.number="form.auto_ytd_min_rs" type="number" min="0" max="100" step="1" required></label><label>目前股票市值（元）<input v-model.number="form.stock_value" type="number" min="0" max="10000000000" required></label><label>目前現金（元）<input v-model.number="form.cash_value" type="number" min="0" max="10000000000" required></label><label>本次分配 ETF 檔數<input v-model.number="form.allocation_count" type="number" min="1" max="12" step="1" required></label><p>股票市值加現金是配置基礎。系統依七項風控因子估計股票目標比例，得出可布局、應調節與保留現金，再優先分配給一年位階較低且 RS、YTD 趨勢仍強的 ETF。配息不是入選條件。</p><button class="primary" :disabled="saving||busy">{{saving?'儲存中':'保存設定'}}</button></form>

  <section v-if="snap?.analysis" class="panel daily-plan-status"><div><span>DAILY ETF PLAN · {{snap.analysis.mode}}</span><h2>{{snap.analysis.date}} 每日滾動配置</h2><p>{{snap.analysis.summary}}</p></div><div class="daily-plan-saved"><b>已保存</b><small>{{stamp(snap.analysis.created_at)}} · 同日預設不重算</small></div></section>
  <section class="panel risk-dashboard" v-if="snap?.risk"><div class="risk-gauge" :style="{'--score':snap.risk.target_equity_pct}"><div><small>建議股票配置</small><strong>{{pct(snap.risk.target_equity_pct)}}</strong><span>風控 {{f(snap.risk.score,1)}} · 覆蓋 {{pct(snap.risk.coverage)}}</span></div></div><div class="risk-summary"><span>目前股票比例</span><strong>{{pct(snap.risk.current_equity_pct)}}</strong><span>股票目標市值</span><strong>{{f(snap.risk.target_stock_value,0)}} 元</strong><span>本次可新增</span><strong class="positive">{{f(snap.risk.deployable,0)}} 元</strong><span>建議調節</span><strong class="negative">{{f(snap.risk.trim_amount,0)}} 元</strong><span>配置後保留現金</span><strong>{{f(snap.risk.trim_amount?snap.risk.post_trim_cash:snap.risk.reserve_cash,0)}} 元</strong><p>{{snap.risk.status}} · 單次目標比例最多變動 7.5 個百分點</p></div></section>
  <section v-if="riskChart&&state?.risk_history" class="panel risk-history"><header><div><span>TAIEX CANDLE · ROLLING ALLOCATION</span><h2>加權指數日 K 與建議股票配置</h2></div><div class="risk-legend"><i class="up"></i>上漲 K <i class="down"></i>下跌 K <i class="ma"></i>20 日均線 <i class="allocation"></i>建議持股％</div></header><div v-if="hoveredRisk" class="risk-tooltip"><b>{{hoveredRisk.date}}</b><span>開 {{f(hoveredRisk.open,2)}}／高 {{f(hoveredRisk.high,2)}}／低 {{f(hoveredRisk.low,2)}}／收 {{f(hoveredRisk.close,2)}}</span><span>20MA {{f(hoveredRisk.ma20,2)}}</span><span v-if="hoveredRisk.target_equity_pct!=null">當日建議 {{pct(hoveredRisk.target_equity_pct)}}<template v-if="hoveredDecision?.trend_20_pct!=null">／20日趨勢 {{pct(hoveredDecision.trend_20_pct)}}</template></span><span v-else>當日尚無保存的配置快照</span></div><div class="risk-chart-scroll"><svg viewBox="0 0 970 370" role="img" aria-label="加權指數日K與每日建議股票配置" @pointermove="moveRisk" @pointerleave="riskHover=null"><g v-for="v in [riskChart.hi,(riskChart.hi+riskChart.lo)/2,riskChart.lo]" :key="v"><line x1="58" x2="918" :y1="224-(v-riskChart.lo)/(riskChart.hi-riskChart.lo)*190" :y2="224-(v-riskChart.lo)/(riskChart.hi-riskChart.lo)*190" stroke="#e6ece2" stroke-dasharray="4 5"/><text x="4" :y="228-(v-riskChart.lo)/(riskChart.hi-riskChart.lo)*190" font-size="11" fill="#87957e">{{f(v,0)}}</text></g><polyline v-if="riskChart.ma20" :points="riskChart.ma20" fill="none" stroke="#c59b4a" stroke-width="2"/><g v-for="(r,i) in riskChart.rows" :key="r.date"><line :x1="r.x" :x2="r.x" :y1="r.highY" :y2="r.lowY" :stroke="r.up?'#c65f51':'#328a67'" stroke-width="1.4"/><rect :x="r.x-r.bodyWidth/2" :y="r.bodyY" :width="r.bodyWidth" :height="r.bodyH" :fill="r.up?'#c65f51':'#328a67'" rx="1"/><rect v-if="r.target_equity_pct!=null" :x="r.x-Math.max(3,r.bodyWidth/2)" :y="r.allocationY!" :width="Math.max(6,r.bodyWidth)" :height="r.allocationH" :fill="r.change_pp==null?'#8da477':r.change_pp<0?'#be8353':'#557e99'" rx="2"/><line v-if="riskHover===i" :x1="r.x" :x2="r.x" y1="27" y2="347" stroke="#98a58f" stroke-dasharray="3 4"/></g><line x1="58" x2="918" y1="248" y2="248" stroke="#dbe3d5"/><text x="4" y="265" font-size="11" fill="#87957e">100%</text><text x="15" y="305" font-size="11" fill="#87957e">50%</text><text x="24" y="347" font-size="11" fill="#87957e">0%</text><text x="58" y="244" font-size="11" fill="#89977e">當日建議持股比例</text></svg></div><footer><span>{{riskChart.start}}</span><span>顯示最近 {{state.risk_history.summary.sessions}} 個交易日 · K 線與配置柱共用日期軸</span><span>{{riskChart.end}}</span></footer><div class="risk-validation"><article><small>最新配置變化</small><b>{{state.risk_history.decisions.at(-1)?.change_pp==null?'建立基準':(state.risk_history.decisions.at(-1)!.change_pp!>0?'+':'')+f(state.risk_history.decisions.at(-1)!.change_pp,1)+'pp'}}</b></article><article><small>加權指數 20 日趨勢</small><b :class="tone(state.risk_history.summary.latest_trend_20_pct)">{{pct(state.risk_history.summary.latest_trend_20_pct)}}</b></article><article><small>趨勢與配置相關</small><b>{{state.risk_history.summary.trend_allocation_correlation==null?'待累積':f(state.risk_history.summary.trend_allocation_correlation,2)}}</b><small>{{state.risk_history.summary.paired_points||0}} 個有效配對日</small></article><article><small>上漲趨勢仍下修</small><b :class="{'negative':(state.risk_history.summary.rising_market_cuts||0)>0}">{{state.risk_history.summary.rising_market_cuts||0}} 次</b></article></div><p class="risk-guidance"><b>{{state.risk_history.summary.guidance}}</b><br>{{state.risk_history.summary.message}}</p><details><summary>驗證方式與限制</summary><p>{{state.risk_history.summary.method}}</p><p>正相關代表大盤20日趨勢轉強時，建議持股通常也提高；負相關則提醒可能在持續上漲時過早降持股。相關性用來校正滾動配置，不能單獨視為買賣訊號。</p></details></section>
  <section v-if="snap?.risk" class="risk-factors"><article v-for="factor in snap.risk.factors" :key="factor.name" class="panel" :class="{missing:!factor.available}"><header><span>{{factor.name}}</span><b>{{factor.available?f(factor.score,0):'待補'}}</b></header><div class="factor-track"><i :style="{width:(factor.score||0)+'%'}"></i></div><p>{{factor.detail}}</p><small>權重 {{factor.weight}}% · {{factor.as_of||'尚無資料日'}}</small></article></section>
  <div class="strategy-cards"><article class="panel"><span>本次可新增布局</span><strong>{{f(snap?.risk?.deployable||0,0)}} <small>元</small></strong><p v-if="snap?.risk?.trim_amount">目前股票高於目標，本次先調節 {{f(snap.risk.trim_amount,0)}} 元</p><p v-else>股票 {{f(snap?.risk?.stock_value||form.stock_value,0)}} ＋ 現金 {{f(snap?.risk?.cash_value||form.cash_value,0)}} 元</p></article><article class="panel"><span>下一檔接棒候選</span><strong>{{snap?.plan?.count||0}} <small>檔 ETF</small></strong><p>{{snap?.plan?.symbols.join('、')||'等待更新'}} · 新增餘額 {{f(snap?.plan?.leftover,0)}} 元</p></article><article class="panel"><span>資料快照</span><strong class="date">{{snap?.date||'待更新'}}</strong><p>YTD 排行 {{snap?.catalog_date||'待更新'}} · 排除槓桿、反向、ETN、期貨型</p></article></div>
  <section v-if="snap?.plan?.rotations?.length" class="panel rotation-board"><header><div><span>PROFIT ROTATION</span><h2>波段獲利調節與接棒預覽</h2></div><strong>{{snap.plan.trim_amount?'調節後':'目前'}}現金 {{f(snap.plan.post_trim_cash,0)}} 元</strong></header><div class="rotation-list"><article v-for="r in snap.plan.rotations" :key="r.from_symbol+'-'+r.to_symbol"><div class="rotation-side trim"><small>接近壓力 · 調節候選</small><b>{{r.from_symbol}} {{r.from_name}}</b><span>{{f(r.preview_amount,0)}} 元 · 上限 {{units(r.from_units)}}</span></div><div class="rotation-arrow">→</div><div class="rotation-side add"><small>靠近支撐才接棒</small><b>{{r.to_symbol}} {{r.to_name}}</b><span>全額輪動預估 {{units(r.to_units)}}</span></div><p>{{r.trigger}}</p></article></div><footer>金額與單位是等額輪動預覽；未輸入各 ETF 實際持有張數與成本，賣出上限不得超過持有數。若風控另有建議調節金額，應先保留所需現金，再考慮輪動其餘部位。</footer></section>
  <div class="strategy-tools"><input v-model="search" placeholder="搜尋 ETF" aria-label="ETF存股搜尋"><label>排序<select v-model="sort"><option value="recommended">本次建議優先</option><option value="position_pct">一年位階低至高</option><option value="ytd_total">YTD 含息報酬高至低</option><option value="drawdown">最大回撤小至大</option><option value="volatility">波動低至高</option></select></label></div>
  <section class="panel strategy-table"><table><thead><tr><th>ETF／入選方式</th><th>一年位階</th><th>波段支撐／壓力</th><th>市價／當日淨值</th><th>YTD 含息／RS</th><th>回撤／波動</th><th>本次動作</th><th>分配／調節金額</th><th>估計單位</th></tr></thead><tbody><tr v-for="e in etfs" :key="e.symbol" :class="{recommended:e.recommended,trim:(e.suggested_trim_amount||0)>0}"><td><button class="symbol" @click="chartSymbol=e.symbol">{{e.symbol}} {{e.name}}</button><small><span class="strategy-badge">{{e.recommended?'接棒候選':e.selection||'自選'}}</span> · {{e.distribution||'配息資料待補'}}</small><small>行情 {{e.as_of||'待補'}} {{e.stale?'· 舊資料':''}}</small></td><td v-if="e.error" colspan="8" class="strategy-gap">{{e.error}}</td><template v-else><td><b>{{e.position_label}} {{pct(e.position_pct)}}</b><small>近一年高低區間</small></td><td><div class="swing-track"><i class="support" :style="{left:levelPos(e.support_1,e)+'%'}"></i><i class="current" :style="{left:levelPos(e.market_price,e)+'%'}"></i><i class="resistance" :style="{left:levelPos(e.resistance_1,e)+'%'}"></i></div><small>S2 {{f(e.support_2)}} · S1 {{f(e.support_1)}}<br>R1 {{f(e.resistance_1)}} · R2 {{f(e.resistance_2)}}</small></td><td>{{f(e.market_price)}} 元<small>淨值 {{e.nav==null?'待官方資料':f(e.nav)+' 元'}}{{e.premium_pct==null?'':' · 溢折 '+pct(e.premium_pct)}}</small></td><td :class="tone(e.ytd_total)">{{pct(e.ytd_total)}}<small>RS {{f(e.rs_ytd,1)}} · 排行漲幅 {{pct(e.rank_ytd)}}</small></td><td>{{pct(e.drawdown)}}<small>波動 {{pct(e.volatility)}}</small></td><td><b>{{e.adjustment_action||e.swing_action}}</b><small>{{e.swing_action}}<br>距支撐 {{pct(e.distance_support_pct)}} · 距壓力 {{pct(e.distance_resistance_pct)}}</small></td><td><b v-if="e.suggested_trim_amount" class="negative">調節 {{f(e.suggested_trim_amount,0)}} 元</b><b v-else>{{f(e.recommended_amount,0)}} 元</b><small v-if="e.rotation_preview_amount">接棒預覽 {{f(e.rotation_preview_amount,0)}} 元</small><small v-else>{{pct(e.allocation_weight)}}{{e.recommended?' · 等待資金':' · 本次不配'}}</small></td><td><b v-if="e.suggested_trim_amount">上限 {{units(e.estimated_trim_units)}}</b><b v-else>{{units(e.estimated_units)}}</b><small v-if="e.estimated_price">預計承接價 {{f(e.estimated_price)}} 元</small><small v-if="e.rotation_units">輪動可買 {{units(e.rotation_units)}}</small><small>估算結果，未送單</small></td></template></tr><tr v-if="!etfs.length"><td colspan="9" class="strategy-empty">手動更新後顯示滾動配置、位階與含息資料。</td></tr></tbody></table></section>
  <section v-if="selected&&!selected.error&&lines" class="panel strategy-chart"><header><h2>{{selected.symbol}} {{selected.name}} · YTD 含息淨值走勢</h2><select v-model="chartSymbol" aria-label="ETF曲線標的"><option v-for="e in etfs.filter(e=>!e.error)" :value="e.symbol">{{e.symbol}} {{e.name}}</option></select></header><div class="legend"><span>● 年初基準 100</span></div><svg viewBox="0 0 940 200" role="img" aria-label="ETF含息淨值走勢"><polyline :points="lines.value" fill="none" stroke="#49775d" stroke-width="3"/></svg><footer><span>{{lines.start}}</span><span>{{lines.end}}</span></footer><div class="swing-levels"><article><small>波段支撐 2</small><b>{{f(selected.support_2)}}</b></article><article><small>波段支撐 1</small><b>{{f(selected.support_1)}}</b></article><article class="now"><small>目前市價</small><b>{{f(selected.market_price)}}</b></article><article><small>波段壓力 1</small><b>{{f(selected.resistance_1)}}</b></article><article><small>波段壓力 2</small><b>{{f(selected.resistance_2)}}</b></article></div><p><b>{{selected.swing_action}}</b> · 相對 0050 含息差距 {{pct(selected.excess_0050)}}（僅同類台股原型適用）。市價 {{f(selected.market_price)}} 元；{{selected.nav_note}}</p><details><summary>配息事件與資料來源</summary><p>{{selected.dividends?.length?'來源列示的除息事件：':'期間來源未列配息事件；可為無配息基金，仍以還原價格計算。'}}</p><p v-for="d in selected.dividends" :key="d.date">{{d.date}} · 每單位 {{f(d.amount,4)}} 元</p><a :href="selected.source" target="_blank" rel="noopener noreferrer">查看行情與配息來源 ↗</a><p>{{selected.limitations}}</p></details></section>
 <details class="strategy-method" open><summary>計算方式與資料範圍</summary><p>{{state?.etf_method}}</p><p>風控因子：小台散戶多空比、外資買賣力道、大盤位階、證交所每日成交金額、恐懼貪婪、台幣與美國利率。社交訊號已移除；其餘因子依原權重正規化，覆蓋低於 70% 時停止新增配置。自動候選採本機 YTD RS 門檻，配息不是條件。當日官方淨值未取得時保留空白，不以市價代替。</p><p>每個交易日預設凍結最新一份完整規劃；一般更新會直接沿用，只有按下「重新分析」才建立同日新版本。更新不會回補分點，也不會呼叫 ChatGPT API。</p><ul v-if="snap?.warnings.length"><li v-for="(w,i) in snap.warnings" :key="i">{{w}}</li></ul></details>
</section>
</template>
